#!/bin/bash
# Runs inside the image build (see Containerfile). Everything here ends up in the OS image.
set -ouex pipefail

### 1. Theme files ---------------------------------------------------------------------
# Our own theme (generated by tools/generate_theme.py) + configs
cp -avf /ctx/system_files/. /
# GTK theme, icons and cursors built from Chicago95 in the assets stage
cp -af /ctx/assets/. /

gtk-update-icon-cache -f -t /usr/share/icons/Chicago95 || true
glib-compile-schemas /usr/share/glib-2.0/schemas/

### 2. Make Classic 7 the system-wide default ---------------------------------------------
# Merge our defaults into /etc/xdg key by key, so Bazzite/Fedora settings we don't touch survive.
merge_ini() {
    local src="$1" dest="$2" group="" line key value
    mkdir -p "$(dirname "$dest")"
    touch "$dest"
    while IFS= read -r line || [[ -n "$line" ]]; do
        [[ -z "$line" || "$line" == \#* ]] && continue
        if [[ "$line" =~ ^\[(.*)\]$ ]]; then
            group="${BASH_REMATCH[1]}"
            continue
        fi
        key="${line%%=*}"
        value="${line#*=}"
        kwriteconfig6 --file "$dest" --group "$group" --key "$key" -- "$value"
    done < "$src"
}

for f in kdeglobals kwinrc dolphinrc; do
    merge_ini "/usr/share/classic7/xdg-defaults/$f" "/etc/xdg/$f"
done

# Fedora's KDE profile also names a default Global Theme; point it at ours too
KDE_PROFILE=/usr/share/kde-settings/kde-profile/default/xdg
if [[ -d "$KDE_PROFILE" ]]; then
    merge_ini /usr/share/classic7/xdg-defaults/kdeglobals "$KDE_PROFILE/kdeglobals"
    merge_ini /usr/share/classic7/xdg-defaults/kwinrc "$KDE_PROFILE/kwinrc"
fi

### 3. Extra software ---------------------------------------------------------------------
# Bazzite already ships Steam, Lutris, GameMode, MangoHud and the AMD stack.
# LACT: fan curve / power limit / undervolt for the RX 7900 XTX.
if ! dnf5 -y install lact; then
    if dnf5 -y copr enable ilyaz/LACT; then
        dnf5 -y install lact || echo "WARNING: LACT not installed"
        dnf5 -y copr disable ilyaz/LACT
    fi
fi
if rpm -q lact; then
    systemctl enable lactd.service
fi

# Quick Launch widget for the taskbar lives in kdeplasma-addons
rpm -q kdeplasma-addons || dnf5 -y install kdeplasma-addons || echo "WARNING: no Quick Launch widget"

# Classic 7 Appearance dialog: Qt for Python (+ Pillow to recolour GTK button images)
dnf5 -y install python3-pyside6 python3-pillow
chmod 0755 /usr/bin/classic7-appearance /usr/bin/classic7-computer /usr/bin/classic7-sendto /usr/bin/classic7-update /usr/libexec/classic7-first-login
python3 -c "import PySide6.QtSvg, PySide6.QtWidgets, PIL"
PYTHONPATH=/usr/lib/classic7 python3 -c "import classic7theme, classic7appearance, drives"
# The Computer window mounts and ejects through UDisks
command -v udisksctl
python3 -m compileall -q /usr/lib/classic7

### 4. Sanity checks: fail the build early if a theme part is missing -------------------
test -f /usr/share/plasma/look-and-feel/org.classic7.desktop/metadata.json
test -f /usr/share/plasma/desktoptheme/classic7/metadata.json
test -f /usr/share/aurorae/themes/Classic7/decoration.svg
test -f /usr/share/color-schemes/Classic7.colors
test -f /usr/share/themes/Classic7/gtk-3.0/gtk.css
test -f /usr/share/icons/Chicago95/index.theme
test -d /usr/share/icons/Chicago95_Standard_Cursors/cursors
grep -q '^LookAndFeelPackage=org.classic7.desktop' /etc/xdg/kdeglobals
# Explorer layout for new accounts
test -f /etc/skel/.local/state/dolphinstaterc
test -f /etc/skel/.local/share/kxmlgui5/dolphin/dolphinui.rc
grep -q '^ShowStatusBar=FullWidth' /etc/xdg/dolphinrc
# Computer window, desktop icons, Win+E
test -x /usr/bin/classic7-computer
test -f /usr/share/applications/classic7-computer.desktop
test -f /usr/share/classic7/desktop/computer.desktop
test -f /etc/xdg/autostart/classic7-first-login.desktop
test -f /etc/skel/.config/kglobalshortcutsrc
# Right-click menus
test -x /usr/bin/classic7-sendto
test -x /usr/bin/classic7-update
test -f /usr/share/kio/servicemenus/classic7-sendto.desktop
test -f /usr/share/kio/servicemenus/classic7-createshortcut.desktop
grep -q '^ShowOpenInNewTab=false' /etc/xdg/dolphinrc

# --- Repositories ------------------------------------------------------------------------
# The installer ISO is built from the repos enabled in this image. A repo whose local
# GPG key file is missing (Bazzite's terra-mesa, for example) makes that build fail, so
# switch such repos off. Installed systems update via the image, not via these repos.
python3 - <<'PY'
import configparser, glob, os, re
for path in glob.glob("/etc/yum.repos.d/*.repo"):
    cp = configparser.RawConfigParser(strict=False)
    try:
        cp.read(path)
    except configparser.Error:
        continue
    bad = set()
    for sec in cp.sections():
        if cp.get(sec, "enabled", fallback="1").strip() != "1":
            continue
        keys = re.split(r"[\s,]+", cp.get(sec, "gpgkey", fallback=""))
        if any(k.startswith("file://") and not os.path.exists(k[7:]) for k in keys):
            bad.add(sec)
    if not bad:
        continue
    out, sec = [], None
    for line in open(path):
        m = re.match(r"\s*\[(.+)\]\s*$", line)
        if m:
            sec = m.group(1)
        elif sec in bad and re.match(r"\s*enabled\s*=\s*1\s*$", line):
            line = "enabled=0\n"
        out.append(line)
    open(path, "w").writelines(out)
    print(f"Disabled repos with missing GPG keys in {path}: {', '.join(sorted(bad))}")
PY
